"use strict";(globalThis.webpackChunkcake_recipes=globalThis.webpackChunkcake_recipes||[]).push([[9081],{48265(e,t,o){o.r(t),o.d(t,{assets:()=>d,contentTitle:()=>c,default:()=>m,frontMatter:()=>l,metadata:()=>n,toc:()=>p});const n=JSON.parse('{"id":"unit-12/mastery-quiz","title":"Unit 12 Mastery Quiz: IMU & Rotation","description":"---","source":"@site/docs/unit-12/12.6-mastery-quiz.mdx","sourceDirName":"unit-12","slug":"/unit-12/mastery-quiz","permalink":"/telemark/docs/unit-12/mastery-quiz","draft":false,"unlisted":false,"editUrl":"https://github.com/sharpfacerobotics/ftc-curriculum/tree/main/docs/unit-12/12.6-mastery-quiz.mdx","tags":[],"version":"current","sidebarPosition":6,"frontMatter":{"id":"mastery-quiz","title":"Unit 12 Mastery Quiz: IMU & Rotation","sidebar_label":"Unit 12 \xb7 Mastery Quiz","sidebar_position":6},"sidebar":"tutorialSidebar","previous":{"title":"12.5 \xb7 Challenge: IMU Turn","permalink":"/telemark/docs/unit-12/imu-turn"},"next":{"title":"Overview","permalink":"/telemark/docs/unit-13"}}');var a=o(74848),i=o(28453),s=o(15432),r=o(8274),h=o(36373);const l={id:"mastery-quiz",title:"Unit 12 Mastery Quiz: IMU & Rotation",sidebar_label:"Unit 12 \xb7 Mastery Quiz",sidebar_position:6},c="Unit 12 Mastery Quiz: IMU & Rotation",d={},p=[{value:"I. Conceptual Questions",id:"i-conceptual-questions",level:2},{value:"II. Debug the Code",id:"ii-debug-the-code",level:2},{value:"III. Scored Check",id:"iii-scored-check",level:2}];function u(e){const t={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",p:"p",pre:"pre",strong:"strong",...(0,i.R)(),...e.components},{Details:o}=t;return o||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"unit-12-mastery-quiz-imu--rotation",children:"Unit 12 Mastery Quiz: IMU & Rotation"})}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"i-conceptual-questions",children:"I. Conceptual Questions"}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"1. Coordinate Transformation:"})," Why is it necessary to pass a ",(0,a.jsx)(t.code,{children:"RevHubOrientationOnRobot"})," object into ",(0,a.jsx)(t.code,{children:"imu.initialize()"})," rather than simply calling the method with no parameters?"]}),"\n",(0,a.jsxs)(o,{children:[(0,a.jsx)("summary",{children:"Show answer"}),(0,a.jsx)(t.p,{children:"The IMU chip inside the Control Hub reports acceleration and rotation along its own internal axes, which are fixed to the circuit board. When the Hub is mounted at any orientation other than flat with the logo up, those internal axes do not align with the field's axes. Without the orientation declaration, the SDK cannot perform the coordinate transformation needed to make Yaw correspond to turning on the field. The result is that heading values are mathematically incorrect for any non-standard mounting. Providing the orientation tells the SDK exactly how to rotate the raw sensor data so that the output always reflects the robot's motion on the field, regardless of how the Hub is physically installed."})]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"2. The Wraparound Problem:"})," When implementing field-centric driving, why must you apply ",(0,a.jsx)(t.code,{children:"AngleUnit.normalizeRadians()"})," to the result of subtracting the robot's heading from the joystick angle, rather than using the raw subtraction result directly?"]}),"\n",(0,a.jsxs)(o,{children:[(0,a.jsx)("summary",{children:"Show answer"}),(0,a.jsxs)(t.p,{children:["Heading values are defined on a circular number line, not a linear one. Subtracting two angles that are on opposite sides of the -\u03c0/\u03c0 boundary produces a result that falls outside the -\u03c0 to \u03c0 range. For example, subtracting -2.9 radians from 2.9 radians gives 5.8 radians. When that value is then fed into ",(0,a.jsx)(t.code,{children:"Math.sin()"})," and ",(0,a.jsx)(t.code,{children:"Math.cos()"})," to reconstruct Cartesian motor commands, it produces the correct mathematical result -- but it represents the long way around the circle rather than the short path the driver intended. ",(0,a.jsx)(t.code,{children:"normalizeRadians()"})," wraps any value back into -\u03c0 to \u03c0, ensuring the motor commands always correspond to the shortest rotation between the joystick direction and the robot's heading."]})]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"3. Relative vs. Absolute Measurement:"})," Why is an IMU-corrected turn considered a closed-loop system, and why does this make it more reliable than a timed turn?"]}),"\n",(0,a.jsxs)(o,{children:[(0,a.jsx)("summary",{children:"Show answer"}),(0,a.jsx)(t.p,{children:"A closed-loop system uses sensor feedback to continuously compare the actual output to the desired output and adjusts accordingly. The IMU turn reads the robot's real heading each loop cycle, calculates the remaining error, and scales motor power to match. If a wheel slips or the battery drops mid-turn, the heading error increases, and the control loop automatically responds by applying more corrective power. A timed turn is open-loop: it applies a fixed output for a fixed duration with no awareness of whether the intended rotation actually occurred. Any disturbance -- battery voltage, floor friction, contact -- directly corrupts the result with no possibility of self-correction."})]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"4. Proportional Gain Tuning:"})," A student sets ",(0,a.jsx)(t.code,{children:"kP = 0.1"})," in their turn-to-angle loop and observes that the robot oscillates back and forth around the target heading rather than settling. Explain what is happening and what adjustment should be made."]}),"\n",(0,a.jsxs)(o,{children:[(0,a.jsx)("summary",{children:"Show answer"}),(0,a.jsxs)(t.p,{children:["A proportional gain that is too large causes the motor power to overshoot the target. When the robot reaches the target, it is still moving at a significant speed because the power was high for most of the turn. It crosses the target, the error reverses sign, power reverses direction, and the robot swings back past the target again. This repeating oscillation is a classic sign of an over-tuned proportional controller. The fix is to reduce ",(0,a.jsx)(t.code,{children:"kP"})," to a smaller value so the motor power scales down more aggressively as the target is approached, giving the robot time to decelerate and settle within the tolerance band."]})]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"5. Pitch, Roll, and the Gravity Vector:"})," From a hardware physics perspective, explain why the IMU can detect that the robot is tilting (pitch and roll) even when the robot is completely stationary on the field."]}),"\n",(0,a.jsxs)(o,{children:[(0,a.jsx)("summary",{children:"Show answer"}),(0,a.jsx)(t.p,{children:"The IMU contains an accelerometer that measures acceleration along each of its axes. When the robot is stationary, the only acceleration acting on it is gravity, which always pulls straight down at approximately 9.8 m/s^2. When the robot is perfectly level, this gravitational acceleration falls entirely along the IMU's vertical axis. When the robot tilts, gravity projects onto the IMU's horizontal axes in proportion to the tilt angle. The accelerometer reads these horizontal projections, and the firmware uses trigonometry to compute the pitch and roll angles from them. The robot does not need to be moving for this to work because gravity is always present as a reference vector."})]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"ii-debug-the-code",children:"II. Debug the Code"}),"\n",(0,a.jsxs)(t.p,{children:["The following code is intended to display the robot's current heading in degrees. ",(0,a.jsx)(t.strong,{children:"Identify and fix the 2 errors."})]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-java",children:'package org.firstinspires.ftc.teamcode;\n\nimport com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;\nimport com.qualcomm.robotcore.eventloop.opmode.TeleOp;\nimport com.qualcomm.robotcore.hardware.IMU;\nimport com.qualcomm.hardware.rev.RevHubOrientationOnRobot;\nimport org.firstinspires.ftc.robotcore.external.navigation.AngleUnit;\n\n@TeleOp(name="IMU_Debug")\npublic class ImuDebug extends LinearOpMode {\n\n    private IMU imu;\n\n    @Override\n    public void runOpMode() {\n        imu = hardwareMap.get(IMU.class, "imu");\n\n        RevHubOrientationOnRobot orientation = new RevHubOrientationOnRobot(\n            RevHubOrientationOnRobot.LogoFacingDirection.UP,\n            RevHubOrientationOnRobot.UsbFacingDirection.FORWARD\n        );\n\n        imu.initialize(orientation);\n\n        waitForStart();\n\n        while (opModeIsActive()) {\n            double heading = imu.getRobotYawPitchRollAngles()\n                                .getPitch(AngleUnit.DEGREES);\n\n            telemetry.addData("Heading (deg)", "%.2f", heading);\n            telemetry.update();\n        }\n    }\n}\n'})}),"\n",(0,a.jsxs)(o,{children:[(0,a.jsx)("summary",{children:"Show answers"}),(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Error 1 -- Syntax/API Error:"}),"\n",(0,a.jsx)(t.code,{children:"imu.initialize()"})," does not accept a ",(0,a.jsx)(t.code,{children:"RevHubOrientationOnRobot"})," object directly. It requires an ",(0,a.jsx)(t.code,{children:"IMU.Parameters"})," object that wraps the orientation. Passing the raw orientation object will either fail to compile or produce an incorrect initialization at runtime."]}),(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-java",children:"imu.initialize(new IMU.Parameters(orientation)); // must wrap in IMU.Parameters\n"})}),(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Error 2 -- Logic Error:"}),"\nThe code calls ",(0,a.jsx)(t.code,{children:".getPitch(AngleUnit.DEGREES)"})," but the intent is to display the heading, which is Yaw. Pitch measures the forward/backward tilt of the robot, not its rotational heading on the field. Displaying pitch as the heading will show a value that is nearly zero when the robot is level and only changes when the robot tips forward or backward, regardless of how far it has turned."]}),(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-java",children:"double heading = imu.getRobotYawPitchRollAngles()\n                    .getYaw(AngleUnit.DEGREES); // getYaw, not getPitch\n"})})]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"iii-scored-check",children:"III. Scored Check"}),"\n",(0,a.jsx)(t.p,{children:"The questions above are for working something through. These are graded, so you can find out whether it stuck. Everything is scored in your browser."}),"\n",(0,a.jsx)(r.A,{lessonId:"unit-12/mastery-quiz",questions:h.o["unit-12"]}),"\n",(0,a.jsx)(s.A,{lessonId:"unit-12/mastery-quiz",nextUnit:"/docs/unit-13/encapsulation",nextUnitName:"Lesson 13.1: Encapsulating Component Logic into Mechanism Classes"})]})}function m(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}},8274(e,t,o){o.d(t,{A:()=>z});var n=o(96540),a=o(61938),i=o(28883),s=o(99991);const r="quiz_cF9Z",h="header_xeWe",l="eyebrow_mc_C",c="title_USD7",d="subtitle_Vm7O",p="body_oW0N",u="question_lZ6r",m="prompt_O7Ua",g="options_Q5yu",w="option_NoJL",f="selected_SAix",y="correct_HcmQ",b="incorrect_Y7uO",v="marker_M_dd",x="explain_wbs2",I="actions_zG_d",k="button_so6H",T="secondary_Jhzk",j="score_NQOG",W="pass_jo16",A="fail_lTo4",M="progressTrack_R2ZB",O="progressFill_ZmTg",S="saved_ejhv";var R=o(74848);function z({lessonId:e,title:t="Scored Check",passMark:o=80,questions:z}){const{user:U}=(0,a.A)(),{markComplete:q,isComplete:C}=(0,i.p)(U),[_,P]=(0,n.useState)(()=>z.map(()=>null)),[N,D]=(0,n.useState)(!1),[E,F]=(0,n.useState)(!1),[L,H]=(0,n.useState)(!1),J=_.filter(e=>null!==e).length,Q=J===z.length,K=(0,n.useMemo)(()=>_.filter((e,t)=>e===z[t].answer).length,[_,z]),$=z.length?Math.round(K/z.length*100):0,B=$>=o;return(0,R.jsxs)("section",{className:r,children:[(0,R.jsxs)("div",{className:h,children:[(0,R.jsxs)("p",{className:l,children:["// ",e,".check"]}),(0,R.jsx)("h3",{className:c,children:t}),(0,R.jsxs)("p",{className:d,children:[z.length," questions. ",o,"% to pass. Answers are graded in your browser and nothing is submitted anywhere."]}),(0,R.jsx)("div",{className:M,"aria-hidden":"true",children:(0,R.jsx)("div",{className:O,style:{width:J/z.length*100+"%"}})})]}),(0,R.jsxs)("div",{className:p,children:[z.map((e,t)=>(0,R.jsxs)("div",{className:u,children:[(0,R.jsxs)("p",{className:m,children:[t+1,". ",e.prompt]}),(0,R.jsx)("div",{className:g,role:"group","aria-label":e.prompt,children:e.options.map((o,n)=>{const a=_[t]===n,i=e.answer===n;let s=w;return N&&i?s=`${w} ${y}`:N&&a&&!i?s=`${w} ${b}`:a&&(s=`${w} ${f}`),(0,R.jsxs)("button",{type:"button",className:s,disabled:N,"aria-pressed":a,onClick:()=>{return e=t,o=n,void(N||P(t=>t.map((t,n)=>n===e?o:t)));var e,o},children:[(0,R.jsx)("span",{className:v,"aria-hidden":"true",children:N&&i?"\u2713":N&&a?"\u2715":String.fromCharCode(65+n)}),(0,R.jsx)("span",{children:o})]},o)})}),N&&(0,R.jsx)("p",{className:x,children:e.explain})]},e.prompt)),(0,R.jsx)("div",{className:I,children:N?(0,R.jsxs)(R.Fragment,{children:[(0,R.jsxs)("span",{className:`${j} ${B?W:A}`,children:[K," / ",z.length," correct (",$,"%)",B?" // passed":" // review and retry"]}),(0,R.jsx)("button",{type:"button",className:`${k} ${T}`,onClick:function(){P(z.map(()=>null)),D(!1),H(!1)},children:"Try again"}),B&&!C(e)&&!L&&(0,R.jsx)("button",{type:"button",className:k,onClick:async function(){F(!0);try{await q(e),H(!0)}catch(t){console.error("Telemark quiz save failed:",t),H(!0)}finally{F(!1)}},disabled:E,children:E?"Saving...":"Record as complete"}),(L||B&&C(e))&&(0,R.jsx)("span",{className:S,children:U?"synced to your account":"saved on this device"})]}):(0,R.jsx)("button",{type:"button",className:k,disabled:!Q,onClick:function(){D(!0),(0,s.s)("quiz_graded",{lesson_id:e,score_percent:$,passed:$>=o})},children:Q?"Grade my answers":z.length-J+" left"})})]})]})}},36373(e,t,o){o.d(t,{o:()=>n});const n={"unit-02":[{prompt:"Which annotation makes a program appear in the Autonomous list on the Driver Station?",options:["@TeleOp","@Autonomous","@Disabled","@Override"],answer:1,explain:"@TeleOp puts it in the driver-controlled list. @Disabled hides it entirely, which is useful for parking an OpMode you are not ready to delete."},{prompt:"In an OpMode, where does hardware mapping belong?",options:["loop()","init()","stop()","It does not matter"],answer:1,explain:"init() runs once before the match. Mapping hardware in loop() repeats the lookup dozens of times per second for no benefit and hides configuration errors until mid-match."},{prompt:"What runs repeatedly while the match is active?",options:["init()","start()","loop()","stop()"],answer:2,explain:"init() and start() each run once, stop() runs once at the end, and loop() repeats. Anything that must respond to the driver goes in loop()."},{prompt:"A motor keeps spinning after the OpMode ends. What is the most likely cause?",options:["The battery is faulty","Power was never set back to zero before the OpMode stopped","The annotation is wrong","loop() ran too fast"],answer:1,explain:"A power command is held until something overrides it. Setting power to zero in stop(), or before returning, is what makes the robot safe."},{prompt:"Why choose LinearOpMode over OpMode for an autonomous routine?",options:["It is faster","It runs a sequence top to bottom with waitForStart(), which suits a planned routine","It is the only one that can use motors","It has no loop"],answer:1,explain:"OpMode is built around a repeating loop, which suits driver control. LinearOpMode runs a sequence, which is how a planned autonomous routine is naturally expressed."}],"unit-03":[{prompt:"Which datatype should hold a motor power value?",options:["int","double","boolean","String"],answer:1,explain:"Power ranges from -1.0 to 1.0 and needs fractional precision. An int would truncate every value to -1, 0, or 1."},{prompt:"What does the expression 7 / 2 evaluate to in Java when both values are int?",options:["3.5","3","4","A compile error"],answer:1,explain:"Integer division truncates toward zero. Writing 7.0 / 2 or casting one operand gives 3.5. This is one of the most common silent bugs in FTC code."},{prompt:"Which type is correct for tracking whether the intake is currently running?",options:["int","double","boolean","String"],answer:2,explain:"A boolean expresses two states directly. Using an int of 0 and 1 works but invites comparisons that the compiler cannot check."},{prompt:"Why declare a constant for a value such as the arm lift power?",options:["It runs faster","It gives the value one home, so changing it does not mean hunting through the file","Java requires it","It uses less memory"],answer:1,explain:"A magic number repeated in four places becomes four different numbers the first time someone tunes it in a hurry."},{prompt:"What type does hardwareMap.get() need in order to identify a device?",options:["A String name matching the robot configuration","An int port number","A double","A boolean"],answer:0,explain:"The name string must match the robot configuration exactly, which is why Unit 7 spends a whole lesson on name mismatches."}],"unit-04":[{prompt:"Why is gamepad1.left_stick_y often negated in drive code?",options:["It is a bug in the SDK","Pushing the stick forward reports a negative value","To make the robot slower","It is not, that is a myth"],answer:1,explain:"The stick axis points down as positive. Negating it once, in one place, means positive always corresponds to forward everywhere else."},{prompt:"What does squaring a joystick input achieve, while preserving its sign?",options:["A higher top speed","Finer control near the center of the stick","It removes the deadzone","Nothing useful"],answer:1,explain:"Squaring compresses small inputs, so the same physical stick movement produces a smaller power change near center, which is where precise driving happens."},{prompt:"What is a deadzone for?",options:["Preventing motion from a stick that does not rest at exactly zero","Limiting the top speed","Saving battery","Making the robot turn faster"],answer:0,explain:"Sticks rarely return to precisely zero. Without a deadzone the robot creeps while nobody is touching the controls."},{prompt:"A button toggle fires many times per press. What is the cause?",options:["The gamepad is broken","loop() runs many times while the button is held, and the previous state is not being tracked","The battery is low","The annotation is wrong"],answer:1,explain:"The fix is to remember the previous button state and act only on the transition from not-pressed to pressed."},{prompt:"What range do the trigger values report?",options:["-1.0 to 1.0","0.0 to 1.0","0 to 255","true or false"],answer:1,explain:"Triggers are one-directional analog inputs from 0.0 to 1.0, unlike sticks which are bidirectional."}],"unit-05":[{prompt:"Which operator tests equality between two int values?",options:["=","==","===","equals()"],answer:1,explain:"A single = assigns. == compares primitives. equals() is for objects, and === is not Java at all."},{prompt:"What does && do when its left side is already false?",options:["Evaluates the right side anyway","Skips the right side entirely","Throws an error","Returns the right side"],answer:1,explain:"Short-circuit evaluation. It is what lets you write a null check on the left and safely use the value on the right."},{prompt:"An else-if chain has an unreachable branch. What is the most likely cause?",options:["Too many branches","An earlier condition is broader and already catches those cases","The braces are wrong","else-if is not valid Java"],answer:1,explain:"Conditions are tested in order, so a broad condition placed first swallows the narrower ones below it. Order from most specific to least."},{prompt:"Why prefer an else-if chain over several separate if statements for mutually exclusive cases?",options:["It is shorter to type","Only one branch can run, so two cannot fire in the same cycle","It runs faster","There is no difference"],answer:1,explain:"Separate ifs are each evaluated independently, so two can both apply and issue conflicting commands to the same motor."},{prompt:"What does the ! operator do?",options:["Compares two values","Inverts a boolean","Ends a statement","Declares a constant"],answer:1,explain:"It negates a boolean, so !isPressed is true exactly when isPressed is false."}],"unit-06":[{prompt:"Why is opModeIsActive() used as a loop condition in LinearOpMode?",options:["It makes the loop faster","It lets the loop exit when the match ends or stop is pressed","It resets the encoders","It is required by Java"],answer:1,explain:"Without it a loop keeps running after stop is pressed, which is both a rules problem and a safety one."},{prompt:"What is wrong with using sleep() to wait for a mechanism during TeleOp?",options:["Nothing","It blocks the whole loop, so nothing else responds while it waits","It uses too much battery","It resets telemetry"],answer:1,explain:"A blocking wait freezes gamepad reading and every other mechanism. A non-blocking timer checked each cycle keeps the robot responsive."},{prompt:"Which is the correct way to time an action without blocking?",options:["Thread.sleep()","Record a start time and compare against elapsed time each cycle","A very long for loop","Repeatedly calling init()"],answer:1,explain:"This is the pattern behind almost every reliable autonomous step and every mechanism that must keep responding while it moves."},{prompt:"What is a for loop most useful for in robot code?",options:["Waiting for a sensor","Applying the same operation across an array of hardware, such as four drive motors","Replacing the OpMode loop","Reading the gamepad"],answer:1,explain:"Iterating an array of motors means configuration is written once rather than copied four times and edited three."},{prompt:"Why store motors in an array?",options:["It is faster at runtime","The same setup can be applied to all of them without repetition","Java requires it","It saves battery"],answer:1,explain:"Repetition is where drift creeps in: three motors get the new mode and the fourth is forgotten."}],"unit-07":[{prompt:"What must the string passed to hardwareMap.get() match?",options:["The Java variable name","The name in the robot configuration on the Driver Station","The motor port number","The class name"],answer:1,explain:"It matches the configuration, not your variable. They are usually named alike by convention, which is exactly why the mismatch is confusing when it happens."},{prompt:"What happens when a hardware name does not exist in the configuration?",options:["The motor silently does nothing","The OpMode throws and stops when it initialises","It defaults to port 0","It logs a warning and continues"],answer:1,explain:"This is helpful: it fails immediately at init rather than halfway through a match."},{prompt:"Why encapsulate a mechanism in its own class?",options:["It runs faster","Its hardware and behaviour live in one place, usable from both TeleOp and Autonomous","Java requires it","It reduces battery draw"],answer:1,explain:"Otherwise the same intake logic is copied into every OpMode and the copies drift apart."},{prompt:"A motor runs backwards relative to its partner on the same side. What is the correct fix?",options:["Negate its power everywhere it is used","Call setDirection(REVERSE) once during init","Rewire the motor","Use a different port"],answer:1,explain:"Setting direction once at the hardware level means every later power command means the same thing everywhere, which manual negation cannot guarantee."},{prompt:"When should hardware be mapped?",options:["Every loop cycle","Once during init","Only in autonomous","When the sensor is first read"],answer:1,explain:"Mapping is a lookup by name. Doing it once at init is both faster and where the failure belongs."}],"unit-08":[{prompt:"What does setPower(1.5) actually do?",options:["Runs the motor at 150%","Is clamped to 1.0 by the SDK","Throws an exception","Stops the motor"],answer:1,explain:"The SDK clamps to the -1.0 to 1.0 range, which protects the hardware from an out-of-range command."},{prompt:"Which ZeroPowerBehavior holds a lift against gravity when power is zero?",options:["FLOAT","BRAKE","COAST","HOLD"],answer:1,explain:"BRAKE shorts the motor terminals, creating resistance. FLOAT disconnects them and lets the lift drift down."},{prompt:"setPower() controls what, most directly?",options:["Velocity in ticks per second","The PWM duty cycle, effectively a voltage fraction","Position in degrees","Current in amps"],answer:1,explain:"Actual speed then depends on battery voltage, load, and run mode, which is why the same power value gives different speeds in different conditions."},{prompt:"A motor hums but does not turn. What should you check first?",options:["The code","Whether the mechanism is stalled against a hard stop or binding","The annotation","Telemetry"],answer:1,explain:"A hum with no motion is a mechanical symptom. Continuing to command power in that state damages the motor."},{prompt:"Why does BRAKE make autonomous more repeatable than coasting?",options:["It is faster","Stopping distance depends on electronic resistance rather than variable friction and battery state","It uses less current","It resets encoders"],answer:1,explain:"Coasting distance varies with battery voltage, tile surface, and weight, so the same routine ends in a different place each run."}],"unit-09":[{prompt:"What range does a standard servo setPosition() accept?",options:["-1.0 to 1.0","0.0 to 1.0","0 to 180","0 to 255"],answer:1,explain:"0.0 to 1.0 maps across the servo's available range. Degrees are a mechanical property, not the API unit."},{prompt:"What does scaleRange() do?",options:["Changes the servo speed","Restricts the usable portion of the servo travel","Reverses the servo","Sets the position"],answer:1,explain:"It is how you stop a claw from driving into its own hard stop while keeping 0.0 and 1.0 as the commands your code uses."},{prompt:"How does a continuous rotation servo differ from a standard one?",options:["It is faster","It is commanded for speed and direction rather than position","It uses more current","It cannot be reversed"],answer:1,explain:"A CR servo has no position feedback, so setPower-style control is what it offers. 0.5 is stop rather than a midpoint."},{prompt:"A servo buzzes continuously while holding a position. What does that indicate?",options:["Normal operation","It is fighting against a load or a hard stop it cannot reach","The battery is full","The code is wrong"],answer:1,explain:"The servo is drawing current trying to reach a commanded position it cannot achieve. Limit the range or fix the mechanical interference."},{prompt:"Why set servo positions during init?",options:["It is required","So the mechanism starts in a known state that fits the size envelope","It makes the servo faster","To reset the encoder"],answer:1,explain:"A servo that starts wherever it was left can put the robot outside its starting envelope, or collide with another mechanism."}],"unit-10":[{prompt:"What does getCurrentPosition() return?",options:["Distance in inches","An accumulated encoder tick count","Degrees of rotation","Motor power"],answer:1,explain:"Ticks are raw counts. Converting them to distance needs the ticks per revolution, the gear ratio, and the wheel circumference."},{prompt:"Which values are needed to convert ticks into inches of travel?",options:["Only ticks per revolution","Ticks per revolution, total gear ratio, and wheel circumference","Battery voltage","The motor power"],answer:1,explain:"The gear ratio and wheel diameter are mechanical decisions, which is why the engineering track covers choosing them."},{prompt:"What must happen before RUN_TO_POSITION will work correctly?",options:["Nothing","A target position must be set and a power supplied as a speed limit","The robot must be stationary","Telemetry must be enabled"],answer:1,explain:"The controller compares current ticks against the target, and the power value caps how fast it closes that gap."},{prompt:"Encoder counts climb while the robot is not moving. What is the likely cause?",options:["The encoder cable is faulty","The wheel is slipping or spinning free","The battery is low","The OpMode is wrong"],answer:1,explain:"The encoder measures the motor, not the ground. This is exactly why dedicated odometry wheels exist."},{prompt:"Why reset encoders before an autonomous routine?",options:["It saves memory","So positions are measured from a known zero rather than from whatever the last run left","It speeds up the motor","It is not necessary"],answer:1,explain:"Without a reset, the second run of the same routine starts from a non-zero count and every target is offset."}],"unit-11":[{prompt:"What does a touch sensor report?",options:["A distance","A boolean pressed state","A colour","An angle"],answer:1,explain:"It is a digital input, which makes it ideal as a limit switch or a homing reference for a slide."},{prompt:"Why check a limit switch before applying power rather than after?",options:["It is faster","So the motor never drives into the hard stop at all","It uses less current","To make telemetry cleaner"],answer:1,explain:"Even a brief moment of full power against an immovable stop spikes current and damages brushes and gear teeth."},{prompt:"What does a potentiometer measure?",options:["A digital on or off","An analog voltage that corresponds to angular position","Distance to an object","Colour"],answer:1,explain:"It gives absolute position without needing a reset, which is its advantage over an encoder for a pivoting arm."},{prompt:"A distance sensor reads erratically at close range. What is the sensible response?",options:["Ignore it","Know the sensor's valid range and treat readings outside it as invalid","Increase the loop speed","Replace the Control Hub"],answer:1,explain:"Every sensor has a range where its output is meaningful. Validating before acting is the difference between a sensor and a random number."},{prompt:"Why validate a sensor reading before acting on it?",options:["It is required by the SDK","A bad reading acted on immediately produces a bad robot action","It makes the loop faster","To reduce current draw"],answer:1,explain:"Sensors return out-of-range and stale values in normal operation, and a mechanism driven by one of them moves for no reason."}],"unit-12":[{prompt:"What does the IMU measure directly?",options:["Distance travelled","Orientation, including yaw","Wheel speed","Battery voltage"],answer:1,explain:"It reports orientation. Position has to come from encoders or odometry, since integrating IMU data for position drifts badly."},{prompt:"Why must the IMU orientation be configured to match how the hub is mounted?",options:["It is optional","Otherwise yaw, pitch, and roll are reported about the wrong axes","It makes it faster","To save power"],answer:1,explain:"A hub mounted vertically reports what your code thinks is yaw as roll, and every heading calculation is then wrong in a confusing way."},{prompt:"What problem does normalising an angle solve?",options:["Sensor noise","The discontinuity when a heading wraps between 180 and -180 degrees","Battery drain","Encoder drift"],answer:1,explain:"Without it, a turn across the wrap point computes an error of nearly 360 degrees and the robot spins the long way around."},{prompt:"What does field-centric driving mean?",options:["The robot drives in circles","Stick directions map to field directions regardless of which way the robot faces","It only works in autonomous","The robot follows a path"],answer:1,explain:"It uses the IMU heading to rotate the driver's input into the robot's frame, so forward on the stick is always forward on the field."},{prompt:"Why monitor pitch and roll?",options:["To measure distance","To detect that the robot is tipping","To improve turning","To read colour"],answer:1,explain:"A tip is detectable before it completes, which gives the code a chance to stop the mechanism that is causing it."}],"unit-13":[{prompt:"What does encapsulation give a mechanism class?",options:["Faster execution","Its internals stay private while it exposes a small, deliberate interface","Less memory use","Automatic testing"],answer:1,explain:"Callers use intake.run() rather than reaching in and setting motor power, so behaviour can change in one place."},{prompt:"What does @Override tell the compiler?",options:["That the method is faster","That this method is intended to replace one in the parent, so a typo becomes a compile error","That the method is private","That the class is abstract"],answer:1,explain:"Without it, a misspelled method name quietly creates a new method that is never called, and the parent behaviour runs instead."},{prompt:"What does static mean on a constant?",options:["It cannot change","It belongs to the class rather than to any instance","It is private","It runs first"],answer:1,explain:"One copy shared by every instance, which is what you want for a tuning value used by all of them. final is what stops it changing."},{prompt:"Why put shared behaviour in a parent class?",options:["Java requires it","So subsystems share one implementation instead of copies that drift apart","It runs faster","It reduces file count"],answer:1,explain:"Copied code diverges the moment someone fixes a bug in one copy and not the other three."},{prompt:"What is the practical benefit of a single Robot class holding the subsystems?",options:["Faster loops","Every OpMode gets the same hardware setup from one place","Smaller files","It is required for autonomous"],answer:1,explain:"Otherwise each OpMode maps hardware itself, and the fifth one written has a subtly different configuration than the first."}],"unit-14":[{prompt:"What does VisionPortal manage?",options:["Motor power","The camera stream and the processors that consume it","Encoder counts","The IMU"],answer:1,explain:"It owns the stream, which is why closing or stopping it when vision is not needed matters for resources."},{prompt:"What does an AprilTag detection provide beyond an identity?",options:["Only the ID","Pose information, giving position and orientation relative to the tag","The battery level","Motor positions"],answer:1,explain:"That pose is what makes a tag useful for localisation rather than just recognition."},{prompt:"Why check that a detection list is not empty before using it?",options:["It is faster","Acting on an absent detection reads a value that is not there","The SDK requires it","To save battery"],answer:1,explain:"A camera sees nothing quite often: bad angle, glare, an obstruction. Code must handle that as a normal case rather than an exception."},{prompt:"What is a region of interest used for?",options:["Making the image brighter","Limiting analysis to the part of the frame where the element can actually be","Increasing frame rate only","Changing the camera angle"],answer:1,explain:"It also reduces false positives, because whatever is outside that region can no longer confuse the detector."},{prompt:"Why stop the camera stream when vision is no longer needed?",options:["It is required by the rules","It frees processing resources that the rest of the loop can use","It resets the encoders","It improves motor torque"],answer:1,explain:"Vision processing is the most expensive thing most FTC robots do, and a loop slowed by it responds late to the driver."}],"unit-15":[{prompt:"What does a path follower such as Pedro Pathing need in order to work?",options:["Only motor power","A reliable estimate of where the robot currently is","A camera","A specific gamepad"],answer:1,explain:"The follower corrects toward a path using the pose estimate. If localisation is wrong, it drives confidently to the wrong place."},{prompt:"What advantage does a B\xe9zier curve have over a sequence of straight segments?",options:["It is easier to code","Continuous motion without stopping to turn at each corner","It needs no tuning","It uses fewer motors"],answer:1,explain:"Stopping and turning at every waypoint costs time, and each stop is another opportunity to accumulate heading error."},{prompt:"When fusing AprilTag localisation with odometry, when should a vision correction be applied?",options:["Always, immediately","Only when the detection passes validity checks such as range and ambiguity","Never in autonomous","Only at the start"],answer:1,explain:"A single bad detection applied without checks teleports the robot's believed position, and the follower then drives hard toward a fiction."},{prompt:"Why keep a simple known-good autonomous routine in the repository?",options:["To pad the code","So the team can still score when the complex routine fails at competition","It is required by inspection","It makes builds faster"],answer:1,explain:"Scoring less beats scoring zero, and the fallback costs nothing to keep once it exists."},{prompt:"A path following routine works in practice and drifts at the event. What should you suspect first?",options:["The Java version","Localisation inputs: measured wheel diameter, pod offsets, and slip on a different field","The gamepad","The annotation"],answer:1,explain:"Tuning is field- and robot-specific, and the mechanical numbers the follower depends on are measured, not assumed."}]};Object.keys(n).length}}]);